CREATE TABLE IF NOT EXISTS reciters (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_ar TEXT);
CREATE TABLE IF NOT EXISTS voiceprints (id INTEGER PRIMARY KEY AUTOINCREMENT, reciter_id TEXT NOT NULL, vec TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL DEFAULT (datetime('now')), predicted_id TEXT NOT NULL, confidence REAL, is_correct INTEGER NOT NULL, actual_id TEXT, actual_name TEXT, vectors TEXT);
CREATE TABLE IF NOT EXISTS reciter_links (id INTEGER PRIMARY KEY AUTOINCREMENT, reciter_id TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL, url TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_links_reciter ON reciter_links(reciter_id);
CREATE TABLE IF NOT EXISTS reciter_bios (reciter_id TEXT PRIMARY KEY, bio TEXT NOT NULL, model TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS rate (ip TEXT NOT NULL, bucket TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (ip, bucket));
CREATE TABLE IF NOT EXISTS model_meta (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS miracle_candidates (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL DEFAULT (datetime('now')), week TEXT, title TEXT NOT NULL, g INTEGER NOT NULL, note TEXT NOT NULL, keys TEXT NOT NULL, model TEXT, score INTEGER, issues TEXT, status TEXT NOT NULL DEFAULT 'pending', topic TEXT NOT NULL DEFAULT 'miracles');
CREATE INDEX IF NOT EXISTS idx_mc_status ON miracle_candidates(status);
